// Tests for the per-grid strict OpenAI schemas (CONTENT-05, D-09).
//
// The committed docs/schema/drill.strict-schema.<grid>.json files are
// generated by scripts/build-strict-schemas.js from the 2x3 template. These
// tests prove they match the builder byte for byte, stay inside OpenAI's
// strict subset, never offer {x, y}, and that a drill in the strict shape
// passes the full schema and the grid lints once post-processed.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'fs';
import { execFileSync } from 'child_process';
import Ajv2020 from 'ajv/dist/2020.js';
import addFormats from 'ajv-formats';
import { buildStrictSchema } from '../scripts/lib/strict-schema.js';
import { lintDrill } from '../scripts/lib/drill-lints.js';

const GRIDS = { '3x3': [3, 3], '3x4': [3, 4], '4x4': [4, 4] };
const range = (n) => Array.from({ length: n }, (_, i) => i + 1);

const schemaUrl = (file) => new URL(`../docs/schema/${file}`, import.meta.url);
const readText = (file) => readFileSync(schemaUrl(file), 'utf8');
const template = JSON.parse(readText('drill.strict-schema.json'));

const BANNED = ['const', 'allOf', 'not', 'if', 'then', 'else', 'dependentRequired', 'dependentSchemas'];

/** Visit every schema node (objects only), with the JSON path to it. */
function walk(node, path, visit) {
  if (Array.isArray(node)) {
    node.forEach((n, i) => walk(n, `${path}/${i}`, visit));
    return;
  }
  if (node === null || typeof node !== 'object') return;
  visit(node, path);
  for (const [k, v] of Object.entries(node)) walk(v, `${path}/${k}`, visit);
}

/** Inline copy of generate.js's post-process (until generate-lib exists). */
function postProcess(drill) {
  for (const step of drill.sequence) {
    if (step.ball && step.ball.action !== 'ROLL' && step.ball.action !== 'PUSH') {
      delete step.ball.from;
      delete step.ball.to;
    }
  }
  return drill;
}

for (const [g, [rows, cols]] of Object.entries(GRIDS)) {
  const file = `drill.strict-schema.${g}.json`;

  test(`${file} is exactly what buildStrictSchema produces`, () => {
    const built = buildStrictSchema(template, g);
    const text = readText(file);
    assert.deepEqual(JSON.parse(text), built);
    assert.equal(text, JSON.stringify(built, null, 2) + '\n');
  });

  const wrapper = JSON.parse(readText(file));
  const schema = wrapper.schema;

  test(`${file} wrapper is strict, named and marked as generated`, () => {
    assert.equal(wrapper.strict, true);
    assert.equal(wrapper.name, `drill_${g}`);
    assert.match(wrapper.name, /^[A-Za-z0-9_-]+$/);
    assert.match(wrapper._source, /GENERATED by scripts\/build-strict-schemas\.js/);
  });

  test(`${file} uses only the OpenAI strict subset`, () => {
    assert.equal(schema.type, 'object');
    assert.ok(!('anyOf' in schema), 'root must not be anyOf');
    walk(schema, '', (node, path) => {
      for (const k of BANNED) {
        assert.ok(!(k in node), `${path} uses unsupported keyword ${k}`);
      }
      if (node.type === 'object') {
        assert.equal(node.additionalProperties, false, `${path} needs additionalProperties: false`);
        const props = Object.keys(node.properties ?? {});
        assert.deepEqual(
          [...(node.required ?? [])].sort(),
          [...props].sort(),
          `${path} must require every property`,
        );
      }
    });
  });

  test(`${file} fixes schema 1.1 and metadata.grid ${g}`, () => {
    assert.deepEqual(schema.properties.schema, { type: 'string', enum: ['1.1'] });
    assert.deepEqual(schema.properties.metadata.properties.grid, { type: 'string', enum: [g] });
    assert.ok(schema.properties.metadata.required.includes('grid'));
    assert.deepEqual(schema.properties.metadata.properties.contributor, {
      type: 'string',
      enum: ['FootworkIQ-AI'],
    });
  });

  test(`${file} cell enums match ${rows} rows x ${cols} cols`, () => {
    const cell = schema.$defs.cell;
    assert.deepEqual(cell.required, ['row', 'col']);
    assert.equal(cell.additionalProperties, false);
    assert.deepEqual(cell.properties.row, { type: 'integer', enum: range(rows) });
    assert.deepEqual(cell.properties.col, { type: 'integer', enum: range(cols) });
    const beat = schema.properties.sequence.items.properties;
    for (const marker of ['left_foot', 'right_foot']) {
      assert.deepEqual(beat[marker].properties.pos, { $ref: '#/$defs/cell' });
    }
    for (const k of ['pos', 'from', 'to']) {
      assert.deepEqual(beat.ball.properties[k], { $ref: '#/$defs/cell' });
    }
    assert.deepEqual([...beat.ball.required].sort(), ['action', 'from', 'pos', 'to']);
  });

  test(`${file} never offers {x, y}`, () => {
    walk(schema, '', (node, path) => {
      if (node.properties) {
        assert.ok(!('x' in node.properties), `${path} has an x property`);
        assert.ok(!('y' in node.properties), `${path} has a y property`);
      }
    });
  });

  test(`${file} compiles with Ajv`, () => {
    const ajv = new Ajv2020({ strict: false, allErrors: true });
    ajv.compile(schema);
  });
}

test('3x4 cell enums are row [1,2,3] and col [1,2,3,4]', () => {
  const cell = buildStrictSchema(template, '3x4').schema.$defs.cell;
  assert.deepEqual(cell.properties.row.enum, [1, 2, 3]);
  assert.deepEqual(cell.properties.col.enum, [1, 2, 3, 4]);
});

test('buildStrictSchema does not mutate the template', () => {
  const before = JSON.stringify(template);
  buildStrictSchema(template, '4x4');
  assert.equal(JSON.stringify(template), before);
});

test('buildStrictSchema rejects 2x3 and unknown grids', () => {
  assert.throws(() => buildStrictSchema(template, '2x3'));
  assert.throws(() => buildStrictSchema(template, '5x5'));
});

test('the 2x3 strict template is unchanged from main', (t) => {
  let onMain;
  try {
    onMain = execFileSync('git', ['show', 'main:docs/schema/drill.strict-schema.json'], {
      cwd: new URL('..', import.meta.url).pathname,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    });
  } catch {
    t.skip('main is not available locally');
    return;
  }
  assert.equal(readText('drill.strict-schema.json'), onMain);
});

test('a strict-shaped 3x3 sample passes the strict schema, the full schema and the lints', () => {
  const sample = JSON.parse(
    readFileSync(new URL('./fixtures/strict/3x3-sample.json', import.meta.url), 'utf8'),
  );

  const strictAjv = new Ajv2020({ strict: false, allErrors: true });
  const strictValidate = strictAjv.compile(JSON.parse(readText('drill.strict-schema.3x3.json')).schema);
  assert.ok(strictValidate(sample), JSON.stringify(strictValidate.errors));

  const drill = postProcess(structuredClone(sample));
  const fullAjv = new Ajv2020({ strict: false, allErrors: true, validateSchema: false });
  addFormats(fullAjv);
  const full = JSON.parse(readText('drill.schema.json'));
  delete full['$schema'];
  const fullValidate = fullAjv.compile(full);
  assert.ok(fullValidate(drill), JSON.stringify(fullValidate.errors));
  assert.deepEqual(lintDrill(drill), []);
});
